+		t.Run(tc.name, func(t *testing.T) {
+			defer func() {
+				r := recover()
+				if tc.shouldPanic {
+					assert.NotNil(t, r, "Expected function to panic, but it didn't")
+				} else {
+					assert.Nil(t, r, "Function panicked unexpectedly")
+				}
+			}()
+
+			ExpandInMetadata(tc.patternMap, tc.resourceMap)
+		})
+	}
+}
